    const bodyColor2 = '#2d3d52'; // 侧面中间色
    const bellyColor = '#3d1a1a'; // 腹部暗红
    const finColor = '#0f1a28'; // 鳍颜色
    const teethColor = '#e8e0d0'; // 牙齿颜色
    const eyeWhite = '#c8c0b0'; // 眼白（偏黄，凶残）
    const eyePupil = '#000'; // 瞳孔
