    ctx.fillStyle = bodyColor2;
    ctx.beginPath();
    ctx.moveTo(size * 0.4, 0);
    ctx.bezierCurveTo(size * 0.2, size * 0.1, -size * 0.1, size * 0.15, -size * 0.2, size * 0.08);
    ctx.lineTo(-size * 0.2, 0);
    ctx.bezierCurveTo(-size * 0.1, 0, size * 0.2, 0, size * 0.4, 0);
