    ctx.ellipse(2.8, -2, 1.8, 2.2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, 0.5);
    ctx.lineTo(-1.2, 3);
    ctx.lineTo(1.2, 3);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = PALETTE.boneDark;
    ctx.lineWidth = 0.4;
    ctx.beginPath();
    ctx.moveTo(-3, 5.5);
    ctx.lineTo(3, 5.5);
    ctx.moveTo(-1.5, 5);
    ctx.lineTo(-1.5, 7);
    ctx.moveTo(0, 5);
    ctx.lineTo(0, 7.5);
