function drawBrassCompass(ctx) {
    ctx.fillStyle = PALETTE.brass;
    ctx.strokeStyle = PALETTE.brassEdge;
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.arc(0, 0, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(240,230,200,0.8)';
    ctx.beginPath();
    ctx.arc(0, 0, 5.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = PALETTE.brassEdge;
    ctx.font = 'bold 3px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('N', 0, -4);
    ctx.fillText('S', 0, 4);
    ctx.fillText('E', 4, 0);
    ctx.fillText('W', -4, 0);
    ctx.textAlign = 'start';
    ctx.textBaseline = 'alphabetic';
    ctx.save();
    ctx.rotate(0.3);
    ctx.fillStyle = '#a03020';
    ctx.beginPath();
    ctx.moveTo(0, -4.5);
    ctx.lineTo(-0.8, 0);
    ctx.lineTo(0.8, 0);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = PALETTE.stoneDark;
    ctx.beginPath();
    ctx.moveTo(0, 4.5);
    ctx.lineTo(-0.8, 0);
    ctx.lineTo(0.8, 0);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = PALETTE.brassEdge;
    ctx.beginPath();
    ctx.arc(0, 0, 0.7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(60,50,40,0.45)';
    ctx.lineWidth = 0.3;
    ctx.beginPath();
    ctx.moveTo(-5, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(5, 3);
    ctx.stroke();
}
