// 兼容微信小游戏的圆角矩形（本文件内部私有工具）
function rrect(c, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    c.moveTo(x + r, y);
    c.lineTo(x + w - r, y);
    c.arcTo(x + w, y, x + w, y + r, r);
    c.lineTo(x + w, y + h - r);
    c.arcTo(x + w, y + h, x + w - r, y + h, r);
    c.lineTo(x + r, y + h);
    c.arcTo(x, y + h, x, y + h - r, r);
    c.lineTo(x, y + r);
    c.arcTo(x, y, x + r, y, r);
    c.closePath();
}
// =============================================
// 入水动效绘制：完全照搬剧情模式（state.transition）的气泡转场观感
// - 200 个气泡随机撒在全屏，速度方向为"从屏幕中心指向自己位置"，持续向外飘散并回绕
// - 气泡造型：纯白主体 + 左上角高亮小点（alpha 比主体大 1.5 倍）
// - 背景：rgba(0,60,100) 半透明覆盖，浓度跟随 alpha（和剧情模式 in 模式一致）
// - 节奏：90 帧总长，前 50 帧 alpha 从 0 渐入到 1，后 40 帧保持 1，到 90 帧后 phase 切 play 瞬接水下场景
// =============================================
function drawMazeDivingIn(maze, cw, ch, time) {
    const timer = maze.divingInTimer;
    const inFrames = 50;
    const alpha = Math.min(1, timer / inFrames);
    const bubbles = maze.divingInBubbles;
    if (!bubbles || bubbles.length === 0) {
        Canvas_1.ctx.fillStyle = `rgba(0, 60, 100, ${alpha})`;
        Canvas_1.ctx.fillRect(0, 0, cw, ch);
        return;
    }
    Canvas_1.ctx.fillStyle = `rgba(0, 60, 100, ${alpha})`;
    Canvas_1.ctx.fillRect(0, 0, cw, ch);
    for (const b of bubbles) {
        b.x += b.vx;
        b.y += b.vy;
        b.wobble += 0.1;
        b.x += Math.sin(b.wobble) * 0.5;
        b.vx *= 0.98;
        b.vy *= 0.98;
        if (b.y < -100)
            b.y = ch + 100;
        if (b.y > ch + 100)
            b.y = -100;
        if (b.x < -100)
            b.x = cw + 100;
        if (b.x > cw + 100)
            b.x = -100;
    }
    for (const b of bubbles) {
        let bodyA = alpha * 0.6;
        if (bodyA > 1)
            bodyA = 1;
        Canvas_1.ctx.fillStyle = `rgba(255, 255, 255, ${bodyA})`;
        Canvas_1.ctx.beginPath();
        Canvas_1.ctx.arc(b.x, b.y, b.size, 0, Math.PI * 2);
        Canvas_1.ctx.fill();
        let highA = bodyA * 1.5;
        if (highA > 1)
            highA = 1;
        Canvas_1.ctx.fillStyle = `rgba(255, 255, 255, ${highA})`;
        Canvas_1.ctx.beginPath();
        Canvas_1.ctx.arc(b.x - b.size * 0.3, b.y - b.size * 0.3, b.size * 0.2, 0, Math.PI * 2);
        Canvas_1.ctx.fill();
    }
}
