function generateArenaMap() {
    const arenaCfg = config_1.CONFIG.fishArena;
    const ts = arenaCfg.tileSize;
    const totalSize = arenaCfg.mapSize;
    const wallThick = arenaCfg.wallThickness;
    // 竞技场格子数
    const cols = Math.ceil(totalSize / ts);
    const rows = Math.ceil(totalSize / ts);
    const wallCols = Math.ceil(wallThick / ts);
    // 重置地图数组
    state_1.state.map = [];
    state_1.state.walls = [];
    state_1.state.plants = [];
    state_1.state.fishes = [];
    state_1.state.explored = [];
    // 初始化：全部填充为岩石（1）
    for (let r = 0; r < rows; r++) {
        state_1.state.map[r] = [];
        state_1.state.explored[r] = [];
        for (let c = 0; c < cols; c++) {
            // 顶部开放（水面），其余三面保留岩石墙
            const inWall = r >= rows - wallCols ||
                c < wallCols || c >= cols - wallCols;
            state_1.state.map[r][c] = inWall ? 1 : 0;
            state_1.state.explored[r][c] = true; // 竞技场全图可见
        }
    }
    // 随机生成大块障碍物（矩形岩石块）
    const obstCount = arenaCfg.obstacleCount;
    const innerLeft = wallCols * ts;
    const innerRight = (cols - wallCols) * ts;
    const innerTop = wallCols * ts;
    const innerBottom = (rows - wallCols) * ts;
    const innerW = innerRight - innerLeft;
    const innerH = innerBottom - innerTop;
    // 玩家出生点（内部中心）
    const spawnX = totalSize / 2;
    const spawnY = totalSize / 2;
    for (let i = 0; i < obstCount; i++) {
        // 随机尝试放置，避免太靠近出生点
        for (let attempt = 0; attempt < 20; attempt++) {
            const ow = arenaCfg.obstacleMinSize + (0, SeededRandom_1.srand)() * (arenaCfg.obstacleMaxSize - arenaCfg.obstacleMinSize);
            const oh = arenaCfg.obstacleMinSize + (0, SeededRandom_1.srand)() * (arenaCfg.obstacleMaxSize - arenaCfg.obstacleMinSize);
            const ox = innerLeft + (0, SeededRandom_1.srand)() * (innerW - ow);
            const oy = innerTop + (0, SeededRandom_1.srand)() * (innerH - oh);
            // 检查与出生点的距离
            const cx = ox + ow / 2;
            const cy = oy + oh / 2;
            if (Math.hypot(cx - spawnX, cy - spawnY) < arenaCfg.obstacleMinDist)
                continue;
            // 将矩形区域填充为岩石
            const r0 = Math.floor(oy / ts);
            const r1 = Math.ceil((oy + oh) / ts);
            const c0 = Math.floor(ox / ts);
            const c1 = Math.ceil((ox + ow) / ts);
            for (let r = r0; r < r1 && r < rows; r++) {
                for (let c = c0; c < c1 && c < cols; c++) {
                    state_1.state.map[r][c] = 1;
                }
            }
            break;
        }
    }
    // 生成墙壁渲染数据（边缘岩石）
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (state_1.state.map[r][c] === 1) {
                let border = isBorderTile(state_1.state.map, r, c, rows, cols);
                if (border) {
                    const offsetX = ((0, SeededRandom_1.srand)() - 0.5) * ts * 0.5;
                    const offsetY = ((0, SeededRandom_1.srand)() - 0.5) * ts * 0.5;
                    const radius = ts * (0.55 + (0, SeededRandom_1.srand)() * 0.35);
                    const wall = {
                        x: c * ts + ts / 2 + offsetX,
                        y: r * ts + ts / 2 + offsetY,
                        r: radius,
                        row: r,
                        col: c,
                        isBorder: true
                    };
                    state_1.state.walls.push(wall);
                    state_1.state.map[r][c] = wall;
                }
                else {
                    state_1.state.map[r][c] = 2;
                }
            }
        }
    }
    // 设置竞技场地标（出生点）
    state_1.state.landmarks.entrance = { x: spawnX, y: spawnY };
    // 竞技场专用 CONFIG 覆盖（临时修改 cols/rows 供碰撞检测使用）
    config_1.CONFIG._arenaRows = rows;
    config_1.CONFIG._arenaCols = cols;
    config_1.CONFIG._arenaTileSize = ts;
}
