                    sideDirY *= -1;
                laneIdxY = clamp(laneIdxY + sideDirY * randInt(1, 2), 0, laneCountY - 1);
                // 横向也稍微移动
                if ((0, SeededRandom_1.srand)() < 0.7) {
                    sideDirX *= -1;
                    laneIdxX = clamp(laneIdxX + sideDirX * randInt(0, 1), 0, laneCountX - 1);
                }
